def _names() -> dict:
    global _MAP
    if _MAP is None:
        _MAP = json.loads(zlib.decompress(base64.b64decode("".join(_NAMES))))
    return _MAP


def font_bytes() -> bytes:
    return zlib.decompress(base64.b64decode("".join(_FONT)))


def resolve(name: str) -> str | None:
    """Название иконки (или похожее английское слово) -> символ шрифта. None - не нашлось."""
    m = _names()
    n = (name or "").strip().lower().replace("_", "-").replace(" ", "-")
    if not n:
        return None
    for cand in (n, SYNONYMS.get(n), SYNONYMS.get(n.rstrip("s")), n.rstrip("s")):
        if cand and cand in m:
            return chr(m[cand])
    words = [w for w in n.split("-") if len(w) > 2]
    for w in words:
        hits = sorted((k for k in m if w in k.split("-")), key=len)
        if hits:
            return chr(m[hits[0]])
    return None


def exists(name: str) -> bool:
    return resolve(name) is not None
